sn_aia_tool.script:
(function(inputs) {
  var result = { status: 'success', captured_failures: [] };
  try {
    var failures = JSON.parse(inputs.failure_data);
    var planId = inputs.plan_id;

    for (var i = 0; i < failures.length; i++) {
      var failure = failures[i];

      var logGr = new GlideRecordSecure('syslog');
      logGr.initialize();
      logGr.setValue('message', 'Plugin Upgrade Failure [' + planId + ']: ' + 
        (failure.plugin_name || 'Unknown') + ' - ' + (failure.error || failure.message || 'No details'));
      logGr.setValue('source', 'x_snc_ai_upgrade_0');
      logGr.setValue('level', '2');
      logGr.insert();

      result.captured_failures.push({
        plugin_name: failure.plugin_name || 'Unknown',
        failure_stage: failure.stage || 'unknown',
        error_message: failure.error || failure.message || 'No error details provided',
        plan_id: planId,
        timestamp: new GlideDateTime().getDisplayValue(),
        logged: true
      });
    }

    result.message = result.captured_failures.length + ' failure(s) captured and logged';
  } catch (e) {
    result.status = 'error';
    result.message = 'Failed to capture failures: ' + e.message;
  }
  return result;
})(inputs);
